ScriptBlock: param(
    [string]$WorkDir = "",
    [string]$ListFile = "",
    [string]$PasswordFile = "",
    [int]$MaxFiles = 25
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$BasePath = $env:TFM_BASEPATH
if ([string]::IsNullOrWhiteSpace($BasePath)) {
    $BasePath = "C:\Users\seguridad\Desktop\TFM\01_ACTIVE_TESTS\Pruebas"
}
$env:TFM_BASEPATH = $BasePath

if ([string]::IsNullOrWhiteSpace($WorkDir)) {
    $WorkDir = Join-Path $BasePath "DUMB_LAB"
}
if ([string]::IsNullOrWhiteSpace($ListFile)) {
    $ListFile = Join-Path $PSScriptRoot "lista_archivos.csv"
}
if ([string]::IsNullOrWhiteSpace($PasswordFile)) {
    $PasswordFile = Join-Path $PSScriptRoot "password.txt"
}

if (-not (Test-Path -LiteralPath $WorkDir)) {
    throw "WorkDir does not exist: $WorkDir"
}
if (-not (Test-Path -LiteralPath $ListFile)) {
    throw "ListFile does not exist: $ListFile"
}
if (-not (Test-Path -LiteralPath $PasswordFile)) {
    Set-Content -LiteralPath $PasswordFile -Value "TFM-Controlled-AES-Key-Only-Dummy-Lab" -Encoding UTF8
}

$password = (Get-Content -LiteralPath $PasswordFile -Raw).Trim()
$sha = [System.Security.Cryptography.SHA256]::Create()
$key = $sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($password))

function Protect-DummyFile {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][byte[]]$Key
    )

    $aes = [System.Security.Cryptography.Aes]::Create()
    $aes.Key = $Key
    $aes.GenerateIV()
    $outPath = "$Path.aes"

    $plainBytes = [System.IO.File]::ReadAllBytes($Path)
    $outStream = [System.IO.File]::Create($outPath)
    try {
        $outStream.Write($aes.IV, 0, $aes.IV.Length)
        $cryptoStream = New-Object System.Security.Cryptography.CryptoStream(
            $outStream,
            $aes.CreateEncryptor(),
            [System.Security.Cryptography.CryptoStreamMode]::Write
        )
        try {
            $cryptoStream.Write($plainBytes, 0, $plainBytes.Length)
            $cryptoStream.FlushFinalBlock()
        }
        finally {
            $cryptoStream.Dispose()
        }
    }
    finally {
        $outStream.Dispose()
        $aes.Dispose()
    }

    Remove-Item -LiteralPath $Path -Force
    return $outPath
}

Write-Host "=== INICIANDO PRUEBA TFM TEC-007 ==="
Write-Host "WorkDir: $WorkDir"
Write-Host "ListFile: $ListFile"

$rows = @(Import-Csv -LiteralPath $ListFile)
$targets = @(
    $rows |
    Where-Object {
        $_.FullName -and
        ($_.FullName -like "$WorkDir*") -and
        (Test-Path -LiteralPath $_.FullName) -and
        ($_.FullName -notlike "*.aes")
    } |
    Select-Object -First $MaxFiles
)

$encrypted = New-Object System.Collections.Generic.List[string]
foreach ($row in $targets) {
    $encrypted.Add((Protect-DummyFile -Path $row.FullName -Key $key)) | Out-Null
}

Write-Host "AES encrypted files: $($encrypted.Count)"
foreach ($path in ($encrypted | Select-Object -First 10)) {
    Write-Host "AES evidence: $path"
}

if ($encrypted.Count -lt 1) {
    throw "No files encrypted. Review DUMB_LAB and lista_archivos.csv."
}

